# ST-GCN-inspired worker for the full tracked UCF101 sequence dataset.
# This file is generated by 05_train_stgcn.ipynb and runs as a separate process.

import os
os.environ.setdefault("OMP_NUM_THREADS", "1")
os.environ.setdefault("MKL_NUM_THREADS", "1")
os.environ.setdefault("OPENBLAS_NUM_THREADS", "1")
os.environ.setdefault("NUMEXPR_NUM_THREADS", "1")

import sys, json, time, random, traceback
from pathlib import Path

import numpy as np
import pandas as pd
import torch
from torch import nn
from torch.utils.data import Dataset, DataLoader
from sklearn.metrics import accuracy_score, balanced_accuracy_score, f1_score, classification_report, confusion_matrix

def log(message, log_path):
    stamp = time.strftime("%Y-%m-%d %H:%M:%S")
    line = f"[{stamp}] {message}"
    print(line, flush=True)
    with open(log_path, "a", encoding="utf-8") as f:
        f.write(line + "\n")

def atomic_torch_save(obj, path):
    path = Path(path)
    tmp = path.with_name(path.stem + ".tmp" + path.suffix)
    torch.save(obj, tmp)
    last_error = None
    for attempt in range(10):
        try:
            os.replace(tmp, path)
            return
        except PermissionError as exc:
            last_error = exc
            time.sleep(min(attempt + 1, 3))
    raise last_error

def set_seed(seed):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)

# COCO-17 skeleton graph, zero-based joint indices.
EDGES = [
    (5, 6), (5, 7), (7, 9), (6, 8), (8, 10),
    (5, 11), (6, 12), (11, 12),
    (11, 13), (13, 15), (12, 14), (14, 16),
    (0, 1), (0, 2), (1, 3), (2, 4)
]
PARENTS = [0, 0, 0, 1, 2, 0, 0, 5, 6, 7, 8, 5, 6, 11, 12, 13, 14]

def make_adjacency():
    n = 17
    a = np.eye(n, dtype=np.float32)
    for i, j in EDGES:
        a[i, j] = 1.0
        a[j, i] = 1.0
    degree = a.sum(axis=1)
    inv_sqrt = np.power(degree, -0.5)
    return (inv_sqrt[:, None] * a * inv_sqrt[None, :]).astype(np.float32)

def build_motion_features(x):
    # Input [B,T,51] = 17 joints * (x,y,confidence).
    # Output [B,8,T,17]: x,y,confidence, velocity-x, velocity-y, speed, bone-x, bone-y.
    b, t, _ = x.shape
    pose = x.reshape(b, t, 17, 3)
    xy = pose[..., :2]
    conf = torch.clamp(torch.nan_to_num(pose[..., 2], nan=0.0), 0.0, 1.0)
    vel = torch.zeros_like(xy)
    if t > 1:
        vel[:, 1:] = xy[:, 1:] - xy[:, :-1]
    speed = torch.linalg.vector_norm(vel, dim=-1, keepdim=True)
    parent_xy = xy[:, :, PARENTS, :]
    bone = xy - parent_xy
    feats = torch.cat([xy, conf.unsqueeze(-1), vel, speed, bone], dim=-1)
    return feats.permute(0, 3, 1, 2).contiguous()

class WindowDataset(Dataset):
    def __init__(self, x_path, y_path, video_path, class_id_to_local, allowed_old_ids):
        self.x = np.load(x_path, mmap_mode="r", allow_pickle=False)
        self.y = np.load(y_path, mmap_mode="r", allow_pickle=False)
        self.videos = np.load(video_path, mmap_mode="r", allow_pickle=False)
        allowed = np.isin(self.y, np.asarray(allowed_old_ids, dtype=self.y.dtype))
        self.indices = np.flatnonzero(allowed).astype(np.int64)
        self.class_id_to_local = class_id_to_local
        self.y_old = np.asarray(self.y[self.indices], dtype=np.int64)
        self.y_local = np.asarray([class_id_to_local[int(v)] for v in self.y_old], dtype=np.int64)
        self.video_ids = np.asarray(self.videos[self.indices], dtype=np.int64)
        if len(self.indices) == 0:
            raise RuntimeError(f"No usable windows found in {x_path}")

    def __len__(self):
        return len(self.indices)

    def __getitem__(self, index):
        real_idx = int(self.indices[index])
        sample = np.asarray(self.x[real_idx], dtype=np.float32)
        return (
            torch.from_numpy(sample),
            torch.tensor(int(self.y_local[index]), dtype=torch.long),
            torch.tensor(int(self.video_ids[index]), dtype=torch.long)
        )

class STGCNBlock(nn.Module):
    def __init__(self, in_channels, out_channels, adjacency, dropout=0.15):
        super().__init__()
        self.register_buffer("adjacency", torch.tensor(adjacency, dtype=torch.float32))
        self.spatial = nn.Conv2d(in_channels, out_channels, kernel_size=1, bias=False)
        self.spatial_bn = nn.BatchNorm2d(out_channels)
        self.temporal = nn.Conv2d(out_channels, out_channels, kernel_size=(3, 1), padding=(1, 0), bias=False)
        self.temporal_bn = nn.BatchNorm2d(out_channels)
        self.dropout = nn.Dropout2d(dropout)
        self.residual = (
            nn.Identity() if in_channels == out_channels else nn.Sequential(
                nn.Conv2d(in_channels, out_channels, kernel_size=1, bias=False),
                nn.BatchNorm2d(out_channels)
            )
        )
        self.activation = nn.ReLU(inplace=True)

    def forward(self, x):
        residual = self.residual(x)
        x = self.activation(self.spatial_bn(self.spatial(x)))
        x = torch.einsum("bctv,vw->bctw", x, self.adjacency)
        x = self.temporal_bn(self.temporal(x))
        x = self.dropout(x)
        return self.activation(x + residual)

class STGCNInspired(nn.Module):
    def __init__(self, num_classes, adjacency):
        super().__init__()
        self.block1 = STGCNBlock(8, 64, adjacency, dropout=0.10)
        self.block2 = STGCNBlock(64, 96, adjacency, dropout=0.15)
        self.block3 = STGCNBlock(96, 128, adjacency, dropout=0.20)
        self.classifier = nn.Sequential(
            nn.Linear(128, 192),
            nn.ReLU(inplace=True),
            nn.Dropout(0.40),
            nn.Linear(192, num_classes)
        )

    def forward(self, x):
        x = build_motion_features(x)
        x = self.block1(x)
        x = self.block2(x)
        x = self.block3(x)
        return self.classifier(x.mean(dim=(2, 3)))

def evaluate(model, loader, device, criterion=None):
    model.eval()
    losses, y_true, y_pred, probs, video_ids = [], [], [], [], []
    with torch.no_grad():
        for xb, yb, vb in loader:
            xb = xb.to(device, non_blocking=(device.type == "cuda"))
            yb = yb.to(device, non_blocking=(device.type == "cuda"))
            logits = model(xb)
            if criterion is not None:
                losses.append(float(criterion(logits, yb).item()))
            p = torch.softmax(logits, dim=1)
            y_true.extend(yb.cpu().numpy().tolist())
            y_pred.extend(logits.argmax(dim=1).cpu().numpy().tolist())
            probs.extend(p.cpu().numpy().tolist())
            video_ids.extend(vb.numpy().tolist())
    y_true = np.asarray(y_true, dtype=np.int64)
    y_pred = np.asarray(y_pred, dtype=np.int64)
    probs = np.asarray(probs, dtype=np.float32)
    video_ids = np.asarray(video_ids, dtype=np.int64)
    observed = np.unique(y_true)
    return {
        "loss": float(np.mean(losses)) if losses else None,
        "accuracy": float(accuracy_score(y_true, y_pred)),
        "balanced_accuracy": float(balanced_accuracy_score(y_true, y_pred)),
        "macro_f1_supported_classes": float(f1_score(y_true, y_pred, labels=observed, average="macro", zero_division=0)),
        "y_true": y_true, "y_pred": y_pred, "probabilities": probs,
        "video_ids": video_ids, "observed_classes": observed,
    }

def main(config_path):
    config = json.loads(Path(config_path).read_text(encoding="utf-8"))
    seq_dir = Path(config["sequence_dir"])
    run_dir = Path(config["run_dir"])
    run_dir.mkdir(parents=True, exist_ok=True)
    log_path = run_dir / "training.log"
    history_path = run_dir / "training_history.csv"
    latest_path = run_dir / "latest_checkpoint.pt"
    best_path = run_dir / "stgcn_best.pt"
    metrics_path = run_dir / "test_metrics.json"

    if config.get("skip_if_complete", True) and metrics_path.is_file() and best_path.is_file():
        log("Final metrics and best checkpoint already exist. Skipping retraining.", log_path)
        return 0

    set_seed(int(config.get("seed", 42)))
    device = torch.device("cuda:0" if config.get("use_cuda", True) and torch.cuda.is_available() else "cpu")
    if config.get("require_cuda", True) and device.type != "cuda":
        raise RuntimeError("CUDA required but unavailable in worker process.")
    log(f"Worker device: {device}", log_path)
    if device.type == "cuda":
        log(f"GPU: {torch.cuda.get_device_name(0)}", log_path)
        log(f"GPU memory GB: {torch.cuda.get_device_properties(0).total_memory / (1024**3):.2f}", log_path)

    label_map_raw = json.loads((seq_dir / "label_map.json").read_text(encoding="utf-8"))
    class_names_by_old = {int(k): str(v) for k, v in label_map_raw.items()}

    y_train_raw = np.load(seq_dir / "y_train.npy", mmap_mode="r", allow_pickle=False)
    y_val_raw = np.load(seq_dir / "y_val.npy", mmap_mode="r", allow_pickle=False)
    y_test_raw = np.load(seq_dir / "y_test.npy", mmap_mode="r", allow_pickle=False)
    train_ids = np.unique(y_train_raw)
    train_supported_old = sorted(int(v) for v in train_ids)
    if not train_supported_old:
        raise RuntimeError("No training classes found.")

    old_to_local = {old: i for i, old in enumerate(train_supported_old)}
    model_class_names = [class_names_by_old[old] for old in train_supported_old]
    val_supported_old = sorted(int(v) for v in np.unique(y_val_raw) if int(v) in old_to_local)
    test_supported_old = sorted(int(v) for v in np.unique(y_test_raw) if int(v) in old_to_local)
    missing_train = [name for old, name in class_names_by_old.items() if old not in old_to_local]
    missing_val = [class_names_by_old[old] for old in train_supported_old if old not in val_supported_old]
    missing_test = [class_names_by_old[old] for old in train_supported_old if old not in test_supported_old]

    log(f"Sequence counts: train={len(y_train_raw):,}, val={len(y_val_raw):,}, test={len(y_test_raw):,}", log_path)
    log(f"Classes with training windows: {len(train_supported_old)}", log_path)
    log(f"Classes without train windows (excluded): {missing_train}", log_path)
    log(f"Train classes without validation windows: {missing_val}", log_path)
    log(f"Train classes without test windows: {missing_test}", log_path)

    train_ds = WindowDataset(seq_dir / "X_train.npy", seq_dir / "y_train.npy", seq_dir / "videos_train.npy", old_to_local, train_supported_old)
    val_ds = WindowDataset(seq_dir / "X_val.npy", seq_dir / "y_val.npy", seq_dir / "videos_val.npy", old_to_local, train_supported_old)
    test_ds = WindowDataset(seq_dir / "X_test.npy", seq_dir / "y_test.npy", seq_dir / "videos_test.npy", old_to_local, train_supported_old)
    if len(val_ds) == 0 or len(test_ds) == 0:
        raise RuntimeError("Validation or test has no windows from train-supported classes.")

    batch_size = int(config.get("batch_size", 8))
    pin_memory = device.type == "cuda"
    train_loader = DataLoader(train_ds, batch_size=batch_size, shuffle=True, num_workers=0, pin_memory=pin_memory)
    val_loader = DataLoader(val_ds, batch_size=batch_size, shuffle=False, num_workers=0, pin_memory=pin_memory)
    test_loader = DataLoader(test_ds, batch_size=batch_size, shuffle=False, num_workers=0, pin_memory=pin_memory)

    counts_local = np.bincount(train_ds.y_local, minlength=len(train_supported_old)).astype(np.float32)
    class_weights = 1.0 / np.sqrt(np.maximum(counts_local, 1.0))
    class_weights = class_weights / class_weights.mean()
    criterion = nn.CrossEntropyLoss(
        weight=torch.tensor(class_weights, dtype=torch.float32, device=device),
        label_smoothing=float(config.get("label_smoothing", 0.05))
    )
    model = STGCNInspired(len(train_supported_old), make_adjacency()).to(device)
    optimizer = torch.optim.AdamW(
        model.parameters(), lr=float(config.get("learning_rate", 5e-4)),
        weight_decay=float(config.get("weight_decay", 1e-4))
    )
    scheduler = torch.optim.lr_scheduler.ReduceLROnPlateau(optimizer, mode="min", factor=0.5, patience=3, min_lr=1e-6)

    start_epoch, best_val_f1, best_val_loss, best_epoch, stale_epochs = 1, -1.0, float("inf"), 0, 0
    history_rows = []
    if config.get("resume", True) and latest_path.is_file():
        checkpoint = torch.load(latest_path, map_location=device, weights_only=False)
        if checkpoint.get("train_class_ids") != train_supported_old:
            raise RuntimeError("Checkpoint class mapping differs from current dataset. Use a new run folder.")
        model.load_state_dict(checkpoint["model_state"])
        optimizer.load_state_dict(checkpoint["optimizer_state"])
        if checkpoint.get("scheduler_state"):
            scheduler.load_state_dict(checkpoint["scheduler_state"])
        start_epoch = int(checkpoint["epoch"]) + 1
        best_val_f1 = float(checkpoint.get("best_val_f1", -1.0))
        best_val_loss = float(checkpoint.get("best_val_loss", float("inf")))
        best_epoch = int(checkpoint.get("best_epoch", 0))
        stale_epochs = int(checkpoint.get("stale_epochs", 0))
        history_rows = checkpoint.get("history_rows", [])
        log(f"Resuming from epoch {start_epoch - 1}.", log_path)

    max_epochs = int(config.get("max_epochs", 50))
    patience = int(config.get("patience", 9))
    save_every = int(config.get("save_every", 5))

    for epoch in range(start_epoch, max_epochs + 1):
        model.train()
        train_losses, train_true, train_pred = [], [], []
        epoch_start = time.time()
        for xb, yb, _ in train_loader:
            xb = xb.to(device, non_blocking=pin_memory)
            yb = yb.to(device, non_blocking=pin_memory)
            optimizer.zero_grad(set_to_none=True)
            logits = model(xb)
            loss = criterion(logits, yb)
            loss.backward()
            nn.utils.clip_grad_norm_(model.parameters(), max_norm=2.0)
            optimizer.step()
            train_losses.append(float(loss.item()))
            train_true.extend(yb.detach().cpu().numpy().tolist())
            train_pred.extend(logits.detach().argmax(dim=1).cpu().numpy().tolist())

        train_true = np.asarray(train_true, dtype=np.int64)
        train_pred = np.asarray(train_pred, dtype=np.int64)
        train_seen = np.unique(train_true)
        train_loss = float(np.mean(train_losses))
        train_acc = float(accuracy_score(train_true, train_pred))
        train_f1 = float(f1_score(train_true, train_pred, labels=train_seen, average="macro", zero_division=0))

        val_result = evaluate(model, val_loader, device, criterion)
        scheduler.step(val_result["loss"])
        val_row = {
            "epoch": epoch, "train_loss": train_loss, "train_accuracy": train_acc,
            "train_macro_f1_supported": train_f1, "val_loss": val_result["loss"],
            "val_accuracy": val_result["accuracy"], "val_balanced_accuracy": val_result["balanced_accuracy"],
            "val_macro_f1_supported_classes": val_result["macro_f1_supported_classes"],
            "learning_rate": float(optimizer.param_groups[0]["lr"]),
            "epoch_seconds": round(time.time() - epoch_start, 2),
        }
        history_rows.append(val_row)
        pd.DataFrame(history_rows).to_csv(history_path, index=False)

        improved = (
            val_result["macro_f1_supported_classes"] > best_val_f1 + 1e-6
            or (abs(val_result["macro_f1_supported_classes"] - best_val_f1) <= 1e-6
                and val_result["loss"] < best_val_loss)
        )
        if improved:
            best_val_f1 = val_result["macro_f1_supported_classes"]
            best_val_loss = float(val_result["loss"])
            best_epoch = epoch
            stale_epochs = 0
        else:
            stale_epochs += 1

        state = {
            "epoch": epoch, "model_state": model.state_dict(),
            "optimizer_state": optimizer.state_dict(), "scheduler_state": scheduler.state_dict(),
            "best_val_f1": best_val_f1, "best_val_loss": best_val_loss,
            "best_epoch": best_epoch, "stale_epochs": stale_epochs, "history_rows": history_rows,
            "train_class_ids": train_supported_old, "class_names": model_class_names,
            "input_shape": [16, 51], "feature_channels": 8,
            "architecture": "ST-GCN-inspired COCO-17 spatial-temporal graph network",
        }
        atomic_torch_save(state, latest_path)
        if improved:
            atomic_torch_save(state, best_path)
        if epoch % save_every == 0:
            atomic_torch_save(state, run_dir / f"checkpoint_epoch_{epoch:03d}.pt")

        log(
            f"Epoch {epoch:02d}/{max_epochs} | train loss={train_loss:.4f} acc={train_acc:.4f} F1={train_f1:.4f} | "
            f"val loss={val_result['loss']:.4f} acc={val_result['accuracy']:.4f} "
            f"bal_acc={val_result['balanced_accuracy']:.4f} macro-F1={val_result['macro_f1_supported_classes']:.4f} | "
            f"best val F1={best_val_f1:.4f} epoch={best_epoch} | seconds={val_row['epoch_seconds']}",
            log_path
        )
        if device.type == "cuda":
            torch.cuda.empty_cache()
        if stale_epochs >= patience:
            log(f"Early stopping at epoch {epoch}; no validation macro-F1 improvement for {patience} epochs.", log_path)
            break

    if not best_path.is_file():
        raise RuntimeError("No best validation checkpoint was saved.")
    best = torch.load(best_path, map_location=device, weights_only=False)
    model.load_state_dict(best["model_state"])
    test_result = evaluate(model, test_loader, device, criterion)
    test_true, test_pred = test_result["y_true"], test_result["y_pred"]
    observed_test = np.unique(test_true)

    report = classification_report(
        test_true, test_pred, labels=observed_test,
        target_names=[model_class_names[int(i)] for i in observed_test],
        output_dict=True, zero_division=0
    )
    pd.DataFrame(report).transpose().to_csv(run_dir / "test_classification_report.csv")

    window_predictions = pd.DataFrame({
        "true_class_id": [train_supported_old[int(i)] for i in test_true],
        "true_label": [model_class_names[int(i)] for i in test_true],
        "predicted_class_id": [train_supported_old[int(i)] for i in test_pred],
        "predicted_label": [model_class_names[int(i)] for i in test_pred],
        "correct": test_true == test_pred,
        "video_id": test_result["video_ids"],
    })
    window_predictions.to_csv(run_dir / "test_window_predictions.csv", index=False)

    cm = confusion_matrix(test_true, test_pred, labels=np.arange(len(train_supported_old)))
    pd.DataFrame(cm, index=model_class_names, columns=model_class_names).to_csv(run_dir / "test_confusion_matrix.csv")

    # Aggregate window probabilities per source video.
    video_rows = []
    probs, video_ids = test_result["probabilities"], test_result["video_ids"]
    for vid in np.unique(video_ids):
        idx = np.flatnonzero(video_ids == vid)
        true_ids = np.unique(test_true[idx])
        if len(true_ids) != 1:
            raise RuntimeError(f"Video {vid} has multiple true labels.")
        mean_prob = probs[idx].mean(axis=0)
        pred_local, true_local = int(np.argmax(mean_prob)), int(true_ids[0])
        video_rows.append({
            "video_id": int(vid),
            "true_class_id": train_supported_old[true_local],
            "true_label": model_class_names[true_local],
            "predicted_class_id": train_supported_old[pred_local],
            "predicted_label": model_class_names[pred_local],
            "correct": bool(pred_local == true_local),
            "windows_aggregated": int(len(idx)),
        })
    video_df = pd.DataFrame(video_rows)
    video_df.to_csv(run_dir / "test_video_predictions.csv", index=False)
    video_true = video_df["true_class_id"].to_numpy()
    video_pred = video_df["predicted_class_id"].to_numpy()
    video_observed = np.unique(video_true)

    metrics = {
        "experiment": "ST-GCN-inspired model on full tracked UCF101 pose sequences",
        "checkpoint": str(best_path),
        "best_epoch": int(best_epoch),
        "best_validation_macro_f1_supported_classes": float(best_val_f1),
        "test_windows": int(len(test_true)),
        "test_window_accuracy": float(accuracy_score(test_true, test_pred)),
        "test_window_balanced_accuracy": float(balanced_accuracy_score(test_true, test_pred)),
        "test_window_macro_f1_supported_classes": float(f1_score(
            test_true, test_pred, labels=observed_test, average="macro", zero_division=0
        )),
        "test_source_videos": int(len(video_df)),
        "test_video_accuracy": float(accuracy_score(video_true, video_pred)),
        "test_video_balanced_accuracy": float(balanced_accuracy_score(video_true, video_pred)),
        "test_video_macro_f1_supported_classes": float(f1_score(
            video_true, video_pred, labels=video_observed, average="macro", zero_division=0
        )),
        "classes_in_model": int(len(train_supported_old)),
        "classes_without_training_windows_excluded": missing_train,
        "training_classes_without_validation_windows": missing_val,
        "training_classes_without_test_windows": missing_test,
        "test_classes_with_support": int(len(observed_test)),
        "device": str(device),
        "batch_size": batch_size,
        "sequence_shape": [16, 51],
        "architecture": "ST-GCN-inspired; 8 channels/joint from pose, confidence, velocity, speed and bone vectors",
        "note": "Metrics are calculated over classes with support in the relevant split. Classes without training windows cannot be learned.",
    }
    (run_dir / "test_metrics.json").write_text(json.dumps(metrics, indent=2), encoding="utf-8")
    log("TRAINING COMPLETE", log_path)
    log(json.dumps(metrics, indent=2), log_path)
    log(f"Best checkpoint: {best_path}", log_path)
    return 0

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: train_stgcn_worker_v3.py <worker_config.json>", file=sys.stderr)
        sys.exit(2)
    try:
        sys.exit(main(sys.argv[1]))
    except Exception:
        traceback.print_exc()
        sys.exit(1)
